import{_ as t,o as s,c as o,ae as i}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"","description":"Create a new Fresh project by running the Fresh project creation tool. This\\nscaffolds out the various files and folders a Fresh project needs.\\n","frontmatter":{"description":"Create a new Fresh project by running the Fresh project creation tool. This\\nscaffolds out the various files and folders a Fresh project needs.\\n"},"headers":[],"relativePath":"en/latest/1.x/getting-started/create-a-project.md","filePath":"en/latest/1.x/getting-started/create-a-project.md"}'),a={name:"en/latest/1.x/getting-started/create-a-project.md"};function n(r,e,l,d,c,h){return s(),o("div",null,[...e[0]||(e[0]=[i(`<p>New Fresh projects can be created by using the Fresh project creation tool. It will scaffold out a new project with some example files to get you started.</p><p>To create a new project, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://fresh.deno.dev</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fresh-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>This will scaffold out the new project, then switch into the newly created directory, and then start the development server.</p><p>This will create a directory containing some files and directories. There are 4 files that are strictly necessary to run a Fresh project:</p><ul><li><strong><code>dev.ts</code></strong>: This is the development entry point for your project. This is the file that you run to start your project. This file doesn&#39;t need to be called <code>dev.ts</code>, but this is the convention.</li><li><strong><code>main.ts</code></strong>: This is the production entry point for your project. It is the file that you link to Deno Deploy. This file doesn&#39;t actually need to be <code>main.ts</code>, but this is the convention.</li><li><strong><code>fresh.gen.ts</code></strong>: This is the manifest file that contains information about your routes and islands. This file is automatically generated in development based on your <code>routes/</code> and <code>islands/</code> folders.</li></ul><p>A <strong><code>deno.json</code></strong> file is also created in the project directory. This file does two things:</p><ul><li>It defines the &quot;imports&quot; field. This is an <a href="https://docs.deno.com/runtime/fundamentals/modules" target="_blank" rel="noreferrer">import map</a> that is used to manage dependencies for the project. This allows for easy importing and updating of dependencies.</li><li>It registers a &quot;start&quot; <a href="https://docs.deno.com/runtime/reference/cli/task" target="_blank" rel="noreferrer">task</a> to run the project without having to type a long <code>deno run</code> command.</li></ul><p>Two important folders are also created that contain your routes and islands respectively:</p><ul><li><strong><code>routes/</code></strong>: This folder contains all of the routes in your project. The name of each file in this folder corresponds to the path where that page will be accessed. Code inside of this folder is never directly shipped to the client. You&#39;ll learn more about how routes work in the next section.</li><li><strong><code>islands/</code></strong>: This folder contains all of the interactive islands in your project. The name of each file corresponds to the name of the island defined in that file. Code inside of this folder can be run from both client and server. You&#39;ll learn more about islands later in this chapter.</li></ul><p>Finally a <strong><code>static/</code></strong> folder is created that contains static files that are automatically served &quot;as is&quot;. <a href="./../concepts/static-files.html">Learn more about static files</a>.</p>`,11)])])}const f=t(a,[["render",n]]);export{u as __pageData,f as default};
